    def test_check_atom_counts_matching_structures(self):
        """Test check_atom_counts with matching structures."""
        # Create two identical structures
        lattice = Lattice.cubic(5.0)
        coords = [[0, 0, 0], [0.5, 0.5, 0.5]]
        struct1 = Structure(lattice, ['Si', 'Si'], coords)
        struct2 = Structure(lattice, ['Si', 'Si'], coords)

        assert check_atom_counts(struct1, struct2) == True

