    def test_check_partially_occupied_sites_no_partial(self):
        """Test check_partially_occupied_sites with fully occupied sites."""
        lattice = Lattice.cubic(5.0)
        struct = Structure(lattice, ['Si'], [[0, 0, 0]])

        assert check_partially_occupied_sites(struct) == False

    def test_check_partially_occupied_sites_with_partial(self):
        """Test check_partially_occupied_sites with partially occupied sites."""
        lattice = Lattice.cubic(5.0)
        # Create a structure with partial occupancy
        struct = Structure(lattice, [{'Si': 0.5, 'C': 0.5}], [[0, 0, 0]])

        assert check_partially_occupied_sites(struct) == True

    def test_check_partially_occupied_sites_mixed(self):
        """Test check_partially_occupied_sites with mixed occupancy."""
        lattice = Lattice.cubic(5.0)
        # One fully occupied, one partially occupied
        struct = Structure(lattice, ['Si', {'C': 0.7, 'N': 0.3}], [[0, 0, 0], [0.5, 0.5, 0.5]])

        assert check_partially_occupied_sites(struct) == True

